def signal(obs):
    # C imbalance predictor only, threshold 0.2
    imb = obs.hist('C','imbalance',5)
    mid = obs.hist('C','mid',5)
    if len(imb)<5 or np.isnan(imb[-1]):
        return {}
    v = imb[-1]
    # also filter? Use rolling? just threshold
    # Strong positive predicts up -> long, negative predicts down -> short
    if v > 0.3:
        return {'C': 0.8}
    elif v < -0.3:
        return {'C': -0.8}
    else:
        return {'C': 0}

def signal(obs):
    st=obs.state
    if 'hold' not in st:
        st['hold']=0
        st['pos']=0
    # decay hold
    if st['hold']>0:
        st['hold']-=10  # called every 10 steps
    imb = obs.hist('C','imbalance',5)
    if len(imb)<2 or np.isnan(imb[-1]):
        return {}
    v=imb[-1]
    # trigger short
    if v < -0.25 and st['hold']<=0:
        st['pos']=-1
        st['hold']=60  # hold 60 steps (~6 calls)
    elif v > 0.3 and st['pos']<0:
        # cover early if large opposite imbalance? maybe stay
        # keep short until hold expires, then go flat unless trigger again
        pass
    if st['hold']<=0:
        st['pos']=0
    # map to target
    if st['pos']==-1:
        return {'C': -0.9}
    else:
        return {'C': 0}

def signal(obs):
    st = obs.state
    if 'hold' not in st:
        st['hold'] = 0
        st['tgt'] = 0.0
    # decrement hold (called ~every 10 steps)
    if st['hold'] > 0:
        st['hold'] -= 10
        if st['hold'] < 0:
            st['hold'] = 0
    # get latest imbalance for C
    try:
        imb = obs.last('C', 'imbalance')
    except:
        imb = float('nan')
    if imb is None or (isinstance(imb, float) and math.isnan(imb)):
        h = obs.hist('C', 'imbalance', 5)
        if len(h) > 0:
            # take last non-nan
            for v in reversed(h):
                if not math.isnan(v):
                    imb = v
                    break
            else:
                imb = 0.0
        else:
            imb = 0.0
    # if currently holding, check early exit on strong opposite imbalance
    if st['hold'] > 0:
        if imb > 0.35:
            st['hold'] = 0
            st['tgt'] = 0.0
            return {'C': 0.0}
        return {'C': float(st['tgt'])}
    # not holding -> flat by default
    # entry condition: significant negative imbalance
    if imb < -0.28:
        # scale size with magnitude: -0.28 -> 0.7, -0.5 -> ~1.0
        mag = abs(imb) - 0.28
        size = 0.7 + mag * 1.4
        if size > 1.0:
            size = 1.0
        if size < 0.5:
            size = 0.5
        st['tgt'] = -size
        st['hold'] = 70
        return {'C': float(st['tgt'])}
    # otherwise stay flat
    if st['tgt'] != 0.0:
        st['tgt'] = 0.0
        return {'C': 0.0}
    return {'C': 0.0}

def signal(obs):
    st = obs.state
    if 'hold' not in st:
        st['hold'] = 0
        st['tgtC'] = 0.0
        st['tgtB'] = 0.0
    # decay hold
    if st['hold'] > 0:
        st['hold'] -= 10
        if st['hold'] < 0:
            st['hold'] = 0
    # helper to get rolling stats
    def get_imb_stats(asset, n=100):
        h = obs.hist(asset, 'imbalance', n)
        # filter nan
        vals = [x for x in h if not math.isnan(x)]
        if len(vals) < 30:
            return 0.0, 1.0, 0.0
        mu = sum(vals)/len(vals)
        var = sum((x-mu)*(x-mu) for x in vals)/len(vals)
        sd = math.sqrt(var) if var>1e-9 else 1.0
        last = vals[-1] if len(vals)>0 else 0.0
        # also last raw maybe nan
        try:
            last_raw = obs.last(asset, 'imbalance')
            if last_raw is not None and not math.isnan(last_raw):
                last = last_raw
        except:
            pass
        return mu, sd, last

    # if holding, keep target and optionally early exit on strong reversal
    if st['hold'] > 0:
        # early cover if strong opposite pressure
        muC, sdC, lastC = get_imb_stats('C', 100)
        zC = (lastC - muC) / (sdC + 1e-9)
        if st['tgtC'] < 0 and zC > 1.8:
            st['hold'] = 0
            st['tgtC'] = 0.0
            st['tgtB'] = 0.0
            return {'C': 0.0, 'B': 0.0}
        if st['tgtC'] > 0 and zC < -1.5:
            st['hold'] = 0
            st['tgtC'] = 0.0
            st['tgtB'] = 0.0
            return {'C': 0.0, 'B': 0.0}
        out = {}
        if st['tgtC'] != 0.0:
            out['C'] = float(st['tgtC'])
        if st['tgtB'] != 0.0:
            out['B'] = float(st['tgtB'])
        if not out:
            out = {'C': 0.0}
        return out

    # not holding -> evaluate new signals
    muC, sdC, lastC = get_imb_stats('C', 100)
    zC = (lastC - muC) / (sdC + 1e-9)
    # B stats for diversification (smaller edge)
    muB, sdB, lastB = get_imb_stats('B', 100)
    zB = (lastB - muB) / (sdB + 1e-9)

    # Extreme negative C -> short C, hold long to let drift exceed spread
    # Threshold z < -1.7 corresponds roughly to raw <-0.3 but adaptive
    if zC < -1.7:
        # size scales with z magnitude, capped
        size = 0.6 + (abs(zC)-1.7)*0.3
        if size > 1.0:
            size = 1.0
        st['tgtC'] = -size
        st['tgtB'] = 0.0
        st['hold'] = 90
        return {'C': float(st['tgtC']), 'B': 0.0}
    # Extreme positive C -> small long (edge smaller, so reduced size and shorter hold)
    if zC > 2.0:
        size = 0.4 + (zC-2.0)*0.2
        if size > 0.7:
            size = 0.7
        st['tgtC'] = size
        st['tgtB'] = 0.0
        st['hold'] = 70
        return {'C': float(st['tgtC']), 'B': 0.0}
    # B positive imbalance long (visible edge 2-4c at 20-50 steps, needs longer hold)
    if zB > 1.9:
        size = 0.5 + (zB-1.9)*0.25
        if size > 0.8:
            size = 0.8
        st['tgtB'] = size
        st['tgtC'] = 0.0
        st['hold'] = 80
        return {'B': float(st['tgtB']), 'C': 0.0}
    # flat
    if st['tgtC'] != 0.0 or st['tgtB'] != 0.0:
        st['tgtC'] = 0.0
        st['tgtB'] = 0.0
        return {'C': 0.0, 'B': 0.0}
    return {'C': 0.0, 'B': 0.0}

