def nc(a,b):
    m=np.isfinite(a)&np.isfinite(b)
    if m.sum()<20:
        return float('nan')
    aa=a[m]; bb=b[m]
    if np.std(aa)==0 or np.std(bb)==0:
        return float('nan')
    return float(np.corrcoef(aa,bb)[0,1])
result={}
for s in ['A','B','C']:
    m1=np.array(H[s]['mid'],dtype=float)
    m2=np.array(H[s+'.X']['mid'],dtype=float)
    d=m1-m2
    for h in [10,50]:
        f1=np.full_like(d,np.nan); f1[:-h]=m1[h:]-m1[:-h]
        f2=np.full_like(d,np.nan); f2[:-h]=m2[h:]-m2[:-h]
        result[s+'_d_to_'+s+'fwd'+str(h)]=nc(d,f1)
        result[s+'_d_to_Xfwd'+str(h)]=nc(d,f2)
        result[s+'_d_to_converg'+str(h)]=nc(d,-(f1-f2))
    dd=d[np.isfinite(d)]
    result[s+'_ac1']=float(np.corrcoef(dd[:-1],dd[1:])[0,1]) if len(dd)>50 else float('nan')
    result[s+'_ac10']=float(np.corrcoef(dd[:-10],dd[10:])[0,1]) if len(dd)>50 else float('nan')
# imbalance / signed volume alpha
for s in ['A','B','C','IDX']:
    imb=np.array(H[s]['imbalance'],dtype=float)
    sv=np.array(H[s]['signed_volume'],dtype=float)
    mid=np.array(H[s]['mid'],dtype=float)
    for h in [10,50]:
        f=np.full_like(mid,np.nan); f[:-h]=mid[h:]-mid[:-h]
        result[s+'_imb_fwd'+str(h)]=nc(imb,f)
        result[s+'_sv_fwd'+str(h)]=nc(sv,f)
# reversal: past 10-step return predicts forward?
for s in ['A','B','C','IDX','A.X','B.X','C.X']:
    mid=np.array(H[s]['mid'],dtype=float)
    past=np.full_like(mid,np.nan); past[10:]=mid[10:]-mid[:-10]
    f10=np.full_like(mid,np.nan); f10[:-10]=mid[10:]-mid[:-10]
    f50=np.full_like(mid,np.nan); f50[:-50]=mid[50:]-mid[:-50]
    result[s+'_rev10_10']=nc(past,f10)
    result[s+'_rev10_50']=nc(past,f50)

def signal(obs):
    mA = obs.last('A','mid')
    mB = obs.last('B','mid')
    mC = obs.last('C','mid')
    mI = obs.last('IDX','mid')
    if mA is None or mB is None or mC is None or mI is None:
        return {}
    if np.isnan(mA) or np.isnan(mB) or np.isnan(mC) or np.isnan(mI):
        return {}
    nav = 0.3333*mA+0.6667*mB+0.1667*mC
    basis = mI-nav
    s = -basis/8.0
    if s>1: s=1.0
    if s<-1: s=-1.0
    if abs(basis)<4.0:
        s=0.0
    return {'IDX': s, 'A': -s*0.3333, 'B': -s*0.6667, 'C': -s*0.1667}

