    mA=obs.last('A','mid'); mB=obs.last('B','mid'); mC=obs.last('C','mid'); mI=obs.last('IDX','mid')
    if mA is None or mB is None or mC is None or mI is None:
        return {}
    if np.isnan(mA) or np.isnan(mB) or np.isnan(mC) or np.isnan(mI):
        return {}
    nav=0.3333*mA+0.6667*mB+0.1667*mC
    basis=mI-nav
    thr=10.0
    if basis<-thr:
        s=1.0
    elif basis>thr:
        s=-1.0
    else:
        s=0.0
    return {'IDX':s,'A':-s*0.3333,'B':-s*0.6667,'C':-s*0.1667}

