# horizon sweep + recency: last 1500 visible steps (closest to holdout) vs earlier
def mom_corr(asset, L, fwd=50, last_n=None):
    mid=H[asset]['mid']
    n=len(mid)
    if last_n is not None:
        mid=mid[-last_n:]
        n=len(mid)
    idxs=list(range(L, n-fwd-1, 10))
    m=[]; f=[]
    for i in idxs:
        a=mid[i-L]; b=mid[i]; c=mid[i+fwd]
        if a!=a or b!=b or c!=c: continue
        m.append(b-a); f.append(c-b)
    m=np.array(m); f=np.array(f)
    if len(m)<20 or np.std(m)==0 or np.std(f)==0:
        return 0.0
    return round(float(np.corrcoef(m,f)[0,1]),3)
result={}
for asset in ['A','B','C']:
    row_full={}
    row_recent={}
    for L in [20,50,100,200,300]:
        row_full[L]=mom_corr(asset,L,last_n=None)
