            if pos==0:
                if mom>thr: npos=1.0
                elif mom<-thr: npos=-1.0
            elif pos>0:
                if mom<0: npos=0.0
            else:
                if mom>0: npos=0.0
        # pnl over next 10 steps: pos * price change (x15 lots)
        if np.isnan(m[t+10]) or np.isnan(m[t]):
            continue
        chg=m[t+10]-m[t]
        s=sprd[t] if not np.isnan(sprd[t]) else 11.0
        cost=0.0
        if npos!=pos:
            cost = s/2.0*15.0*abs(npos-pos)  # crossing spread on change
