def signal(obs):
    s=obs.state
    if 'posC' not in s:
        s['posC']=0.0
        s['holdC']=0
        s['posS']=0.0
        s['holdS']=0
    # --- C momentum with 0.8 vol filter, hold 20 steps ---
    if s['holdC']>0:
        s['holdC']-=1
    else:
        try:
            mids = obs.hist('C','mid',31)
            if len(mids)>=11 and np.isfinite(mids[-1]) and np.isfinite(mids[-11]):
                past = mids[-1] - mids[-11]  # h=10
                diffs = np.diff(mids)
                diffs = diffs[np.isfinite(diffs)]
                if len(diffs)>=10:
                    v = np.nanstd(diffs)
                    vol_h = v * (10**0.5) if v>1e-9 else 5.0
                else:
                    vol_h = 5.0
                if vol_h < 1e-6:
                    vol_h = 5.0
                score = past / vol_h
                if score > 0.8:
                    s['posC']=1.0
                    s['holdC']=20
                elif score < -0.8:
                    s['posC']=-1.0
                    s['holdC']=20
                else:
                    s['posC']=0.0
            else:
                s['posC']=0.0
        except:
            s['posC']=0.0
    # --- IDX synthetic mean reversion, short only (only large premiums profitable net) ---
    if s['holdS']>0:
        s['holdS']-=1
    else:
        try:
            mA=obs.last('A','mid'); mB=obs.last('B','mid'); mC=obs.last('C','mid'); mI=obs.last('IDX','mid')
            if mA is None or mB is None or mC is None or mI is None:
                s['posS']=0.0
            elif not np.isfinite(mA) or not np.isfinite(mB) or not np.isfinite(mC) or not np.isfinite(mI):
                s['posS']=0.0
            else:
                syn=0.3333*mA+0.6667*mB+0.1667*mC
                sp=mI-syn
                if sp>30:
                    s['posS']=-1.0
                    s['holdS']=50
                elif sp>22:
                    s['posS']=-0.6
                    s['holdS']=30
                else:
                    s['posS']=0.0
        except:
            s['posS']=0.0
    scale=0.6
    wA=-0.3333*scale*s['posS']
    wB=-0.6667*scale*s['posS']
    wC_arb=-0.1667*scale*s['posS']
    wI=scale*s['posS']
    wC = wC_arb + float(s['posC'])
    def clip(x):
        if x>1: return 1.0
        if x<-1: return -1.0
        return float(x)
    return {'A':clip(wA),'B':clip(wB),'C':clip(wC),'IDX':clip(wI),'A.X':0.0,'B.X':0.0,'C.X':0.0}

