        s['p']={}
        s['h']={}
        for k in ['B','C']:
            s['p'][k]=0.0
            s['h'][k]=0
        s['posS']=0.0
        s['holdS']=0
    for asset, xasset in [('B','B.X'),('C','C.X')]:
        if s['h'][asset]>0:
            s['h'][asset]-=1
        else:
            try:
                mids=obs.hist(xasset,'mid',45)
                if len(mids)>=21 and np.isfinite(mids[-1]) and np.isfinite(mids[-21]):
                    past=mids[-1]-mids[-21]
                    diffs=np.diff(mids)
                    diffs=diffs[np.isfinite(diffs)]
                    if len(diffs)>=20:
                        v=np.nanstd(diffs)
                        vol=v*(20**0.5) if v>1e-9 else 5.0
                    else:
                        vol=5.0
                    if vol<1e-6:
                        vol=5.0
                    score=past/vol
                    if score>0.8:
                        s['p'][asset]=1.0
                        s['h'][asset]=20
                    elif score<-0.8:
                        s['p'][asset]=-1.0
                        s['h'][asset]=20
                    else:
                        s['p'][asset]=0.0
                else:
                    s['p'][asset]=0.0
            except:
                s['p'][asset]=0.0
    if s['holdS']>0:
        s['holdS']-=1
    else:
        try:
            mA=obs.last('A','mid'); mB=obs.last('B','mid'); mC=obs.last('C','mid'); mI=obs.last('IDX','mid')
            if None in (mA,mB,mC,mI) or not (np.isfinite(mA) and np.isfinite(mB) and np.isfinite(mC) and np.isfinite(mI)):
                s['posS']=0.0
            else:
                syn=0.3333*mA+0.6667*mB+0.1667*mC
                sp=mI-syn
                if sp>30:
                    s['posS']=-1.0
                    s['holdS']=50
                elif sp>22:
                    s['posS']=-0.6
                    s['holdS']=30
