# Check lead-lag: does C.X momentum predict C forward returns? vs C momentum predicts C?
def corr(a,b):
    a=np.array(a,float); b=np.array(b,float)
    m=np.isfinite(a)&np.isfinite(b)
    if m.sum()<100: return float('nan')
    a=a[m]; b=b[m]
    am=a.mean(); bm=b.mean()
    sa=((a-am)**2).mean()**0.5; sb=((b-bm)**2).mean()**0.5
    if sa==0 or sb==0: return float('nan')
    return float(((a-am)*(b-bm)).mean()/sa/sb)

